    public function filterByBpmnProcess($bpmnProcess, $comparison = null)
    {
        if ($bpmnProcess instanceof BpmnProcess) {
            return $this
                ->addUsingAlias(WorkflowConfigurationPeer::BPMNPROCESS_ID, $bpmnProcess->getBpmnprocessId(), $comparison);
        } elseif ($bpmnProcess instanceof PropelObjectCollection) {
            if (null === $comparison) {
                $comparison = Criteria::IN;
            }

            return $this
                ->addUsingAlias(WorkflowConfigurationPeer::BPMNPROCESS_ID, $bpmnProcess->toKeyValue('PrimaryKey', 'BpmnprocessId'), $comparison);
        } else {
            throw new PropelException('filterByBpmnProcess() only accepts arguments of type BpmnProcess or PropelCollection');
        }
    }

    /**
     * Adds a JOIN clause to the query using the BpmnProcess relation
     *
     * @param     string $relationAlias optional alias for the relation
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return WorkflowConfigurationQuery The current query, for fluid interface
     */
    public function joinBpmnProcess($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        $tableMap = $this->getTableMap();
        $relationMap = $tableMap->getRelation('BpmnProcess');

        // create a ModelJoin object for this join
        $join = new ModelJoin();
        $join->setJoinType($joinType);
        $join->setRelationMap($relationMap, $this->useAliasInSQL ? $this->getModelAlias() : null, $relationAlias);
        if ($previousJoin = $this->getPreviousJoin()) {
            $join->setPreviousJoin($previousJoin);
        }

        // add the ModelJoin to the current object
        if ($relationAlias) {
            $this->addAlias($relationAlias, $relationMap->getRightTable()->getName());
            $this->addJoinObject($join, $relationAlias);
        } else {
            $this->addJoinObject($join, 'BpmnProcess');
        }

        return $this;
    }

    /**
     * Use the BpmnProcess relation BpmnProcess object
     *
