     */
    public function useBpmnProcessQuery($relationAlias = null, $joinType = Criteria::INNER_JOIN)
    {
        return $this
            ->joinBpmnProcess($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'BpmnProcess', 'BpmnProcessQuery');
    }

    /**
